description:
A mobile-first experimental digital signage management platform for provisioning media, playlists, templates, and devices, featuring a comprehensive Support & Knowledge Hub. New design: <!DOCTYPE html>
<html lang="en">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>Edge Signage Runtime v3.0</title>
    <script src="https://cdn.tailwindcss.com"></script>
    <script src="https://unpkg.com/react@18/umd/react.production.min.js"></script>
    <script src="https://unpkg.com/react-dom@18/umd/react-dom.production.min.js"></script>
    <script src="https://unpkg.com/@babel/standalone/babel.min.js"></script>
    <script src="https://unpkg.com/lucide@latest"></script>
    <script src="https://cdn.jsdelivr.net/npm/chart.js"></script>
    <link rel="preconnect" href="https://fonts.googleapis.com">
    <link rel="preconnect" href="https://fonts.gstatic.com" crossorigin>
    <link href="https://fonts.googleapis.com/css2?family=Inter:wght@300;400;500;600;700&family=JetBrains+Mono:wght@400;500;600;700&display=swap" rel="stylesheet">

    <script>
        tailwind.config = {
            theme: {
                extend: {
                    colors: {
                        primary: 'hsl(187 100% 50%)',
                        accent: 'hsl(270 80% 65%)',
                        background: 'hsl(222 47% 6%)',
                        foreground: 'hsl(210 40% 92%)',
                        card: 'hsl(222 40% 9%)',
                        muted: 'hsl(222 30% 14%)',
                        destructive: 'hsl(0 72% 55%)',
                        success: 'hsl(142 76% 36%)',
                        warning: 'hsl(38 92% 50%)',
                    },
                    fontFamily: {
                        sans: ['Inter', 'sans-serif'],
                        mono: ['JetBrains Mono', 'monospace'],
                    },
                    borderRadius: {
                        xl: '0.75rem',
                        '2xl': '1rem',
                    },
                    boxShadow: {
                        'glow-cyan': '0 0 20px rgba(6, 182, 212, 0.15)',
                        'glow-purple': '0 0 20px rgba(168, 85, 247, 0.15)',
                        'glow-card': '0 0 30px rgba(6, 182, 212, 0.05)',
                    }
                }
            }
        }
    </script>
    <style>
        * { -webkit-tap-highlight-color: transparent; }
        body { 
            background: hsl(222 47% 6%); 
            color: hsl(210 40% 92%);
            font-family: 'Inter', sans-serif;
            overflow-x: hidden;
        }
        .scrollbar-hide::-webkit-scrollbar { display: none; }
        .scrollbar-hide { -ms-overflow-style: none; scrollbar-width: none; }

        .glass-card {
            background: rgba(15, 23, 42, 0.6);
            backdrop-filter: blur(12px);
            border: 1px solid rgba(255, 255, 255, 0.05);
        }

        .glow-border-cyan {
            position: relative;
        }
        .glow-border-cyan::before {
            content: '';
            position: absolute;
            inset: -1px;
            border-radius: inherit;
            padding: 1px;
            background: linear-gradient(135deg, rgba(6,182,212,0.3), transparent 50%);
            -webkit-mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
            mask: linear-gradient(#fff 0 0) content-box, linear-gradient(#fff 0 0);
            -webkit-mask-composite: xor;
            mask-composite: exclude;
            pointer-events: none;
        }

        @keyframes pulse-glow {
            0%, 100% { box-shadow: 0 0 15px rgba(6, 182, 212, 0.1); }
            50% { box-shadow: 0 0 25px rgba(6, 182, 212, 0.2); }
        }
        .animate-pulse-glow { animation: pulse-glow 3s ease-in-out infinite; }

        @keyframes slide-up {
            from { opacity: 0; transform: translateY(10px); }
            to { opacity: 1; transform: translateY(0); }
        }
        .animate-slide-up { animation: slide-up 0.3s ease-out; }

        .status-dot {
            box-shadow: 0 0 8px currentColor;
        }

        .chart-container { position: relative; height: 200px; width: 100%; }

        .nav-item-active {
            background: linear-gradient(90deg, rgba(6,182,212,0.1) 0%, transparent 100%);
            border-left: 3px solid hsl(187 100% 50%);
        }

        .sequencer-dot {
            transition: all 0.3s ease;
        }
        .sequencer-dot.active {
            background: hsl(187 100% 50%);
            box-shadow: 0 0 12px hsl(187 100% 50%);
            transform: scale(1.2);
        }

        input, select, textarea {
            background: hsl(222 30% 14%);
            border: 1px solid rgba(255,255,255,0.1);
            color: inherit;
        }
        input:focus, select:focus, textarea:focus {
            outline: none;
            border-color: hsl(187 100% 50%);
            box-shadow: 0 0 0 2px rgba(6,182,212,0.1);
        }
    </style>
</head>
<body>
    <div id="root"></div>

    <script type="text/babel">
        const { useState, useEffect, useRef, useCallback, createContext, useContext } = React;

        // --- Data Store ---
        const initialPlaylists = [
            {
                id: 'pl_1',
                name: 'Lobby Display — Q2 Campaign',
                description: 'Main lobby promotional content for Q2 product launch',
                items: [
                    { id: 'item_1', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', name: 'Q2 Hero Video', duration: 15000, transition: 'fade', order: 0 },
                    { id: 'item_2', type: 'image', url: 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=800', name: 'Product Shot A', duration: 8000, transition: 'slide', order: 1 },
                    { id: 'item_3', type: 'image', url: 'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?w=800', name: 'Product Shot B', duration: 8000, transition: 'cut', order: 2 },
                    { id: 'item_4', type: 'html', url: 'data:text/html,<html><body style="margin:0;background:linear-gradient(45deg,%2300d4ff,%237c3aed);display:flex;align-items:center;justify-content:center;height:100vh;color:white;font-family:sans-serif;"><h1>SPECIAL OFFER<br>25% OFF</h1></body></html>', name: 'Promo Overlay', duration: 10000, transition: 'fade', order: 3 }
                ],
                status: 'active',
                loop: true,
                version: 3
            },
            {
                id: 'pl_2',
                name: 'Retail Window — Summer Sale',
                description: 'Summer sale campaign for retail storefront displays',
                items: [
                    { id: 'item_5', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4', name: 'Summer Vibes', duration: 12000, transition: 'fade', order: 0 },
                    { id: 'item_6', type: 'image', url: 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800', name: 'Sale Banner', duration: 6000, transition: 'cut', order: 1 }
                ],
                status: 'active',
                loop: true,
                version: 1
            },
            {
                id: 'pl_3',
                name: 'Corporate — Brand Loop',
                description: 'Internal corporate branding and announcements',
                items: [
                    { id: 'item_7', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', name: 'Brand Story', duration: 15000, transition: 'fade', order: 0 }
                ],
                status: 'draft',
                loop: false,
                version: 2
            }
        ];

        const initialDevices = [
            {
                id: 'dev_1',
                name: 'Lobby-North-01',
                device_id: 'ES-84F2-A1',
                platform: 'tizen',
                status: 'online',
                assigned_playlist: 'pl_1',
                shadow_state: { desired: { playlist: 'pl_1', volume: 80, brightness: 100 }, reported: { playlist: 'pl_1', volume: 80, brightness: 100 }, version: 12 },
                health: { state: 'OK', memory_usage: 45, frame_drops: 0, uptime_hours: 720, last_heartbeat: Date.now() - 30000, decode_errors: 0 },
                resolution: '3840x2160',
                location: 'Main Lobby North',
                group: 'lobby_group'
            },
            {
                id: 'dev_2',
                name: 'Retail-Window-02',
                device_id: 'ES-84F2-B2',
                platform: 'webos',
                status: 'online',
                assigned_playlist: 'pl_2',
                shadow_state: { desired: { playlist: 'pl_2', volume: 70, brightness: 90 }, reported: { playlist: 'pl_2', volume: 70, brightness: 90 }, version: 8 },
                health: { state: 'OK', memory_usage: 62, frame_drops: 2, uptime_hours: 480, last_heartbeat: Date.now() - 45000, decode_errors: 0 },
                resolution: '1920x1080',
                location: 'Storefront East',
                group: 'retail_group'
            },
            {
                id: 'dev_3',
                name: 'Conf-Room-A',
                device_id: 'ES-84F2-C3',
                platform: 'android_tv',
                status: 'degraded',
                assigned_playlist: 'pl_3',
                shadow_state: { desired: { playlist: 'pl_3', volume: 60, brightness: 100 }, reported: { playlist: 'pl_3', volume: 60, brightness: 95 }, version: 5 },
                health: { state: 'DEGRADED', memory_usage: 89, frame_drops: 12, uptime_hours: 120, last_heartbeat: Date.now() - 120000, decode_errors: 3 },
                resolution: '1920x1080',
                location: 'Conference Room A',
                group: null
            },
            {
                id: 'dev_4',
                name: 'Cafeteria-04',
                device_id: 'ES-84F2-D4',
                platform: 'electron',
                status: 'online',
                assigned_playlist: 'pl_1',
                shadow_state: { desired: { playlist: 'pl_1', volume: 75, brightness: 85 }, reported: { playlist: 'pl_1', volume: 75, brightness: 85 }, version: 15 },
                health: { state: 'OK', memory_usage: 38, frame_drops: 0, uptime_hours: 960, last_heartbeat: Date.now() - 15000, decode_errors: 0 },
                resolution: '2560x1440',
                location: 'Employee Cafeteria',
                group: 'cafeteria_group'
            },
            {
                id: 'dev_5',
                name: 'Loading-Dock-05',
                device_id: 'ES-84F2-E5',
                platform: 'browser',
                status: 'offline',
                assigned_playlist: null,
                shadow_state: { desired: { playlist: null, volume: 50, brightness: 100 }, reported: { playlist: null, volume: 50, brightness: 100 }, version: 3 },
                health: { state: 'CRITICAL', memory_usage: 0, frame_drops: 0, uptime_hours: 0, last_heartbeat: Date.now() - 86400000, decode_errors: 0 },
                resolution: '1920x1080',
                location: 'Loading Dock',
                group: null
            }
        ];

        const initialAssets = [
            { id: 'asset_1', name: 'Q2 Hero Video', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/BigBuckBunny.mp4', size_bytes: 15800000, duration_ms: 15000, content_hash: 'a1b2c3', status: 'ready', dimensions: '1920x1080' },
            { id: 'asset_2', name: 'Product Shot A', type: 'image', url: 'https://images.unsplash.com/photo-1558618666-fcd25c85f82e?w=800', size_bytes: 2400000, duration_ms: 0, content_hash: 'd4e5f6', status: 'cached', dimensions: '1920x1080' },
            { id: 'asset_3', name: 'Product Shot B', type: 'image', url: 'https://images.unsplash.com/photo-1560472354-b33ff0c44a43?w=800', size_bytes: 2100000, duration_ms: 0, content_hash: 'g7h8i9', status: 'cached', dimensions: '1920x1080' },
            { id: 'asset_4', name: 'Summer Vibes', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ElephantsDream.mp4', size_bytes: 12400000, duration_ms: 12000, content_hash: 'j0k1l2', status: 'ready', dimensions: '1920x1080' },
            { id: 'asset_5', name: 'Sale Banner', type: 'image', url: 'https://images.unsplash.com/photo-1441986300917-64674bd600d8?w=800', size_bytes: 1800000, duration_ms: 0, content_hash: 'm3n4o5', status: 'ready', dimensions: '1920x1080' },
            { id: 'asset_6', name: 'Brand Story', type: 'video', url: 'https://commondatastorage.googleapis.com/gtv-videos-bucket/sample/ForBiggerBlazes.mp4', size_bytes: 14200000, duration_ms: 15000, content_hash: 'p6q7r8', status: 'ready', dimensions: '1920x1080' }
        ];

        // --- Context ---
        const AppContext = createContext();

        const AppProvider = ({ children }) => {
            const [currentPage, setCurrentPage] = useState('dashboard');
            const [playlists, setPlaylists] = useState(initialPlaylists);
            const [devices, setDevices] = useState(initialDevices);
            const [assets, setAssets] = useState(initialAssets);
            const [sidebarOpen, setSidebarOpen] = useState(false);
            const [playerState, setPlayerState] = useState({
                isPlaying: false,
                currentPlaylist: null,
                currentIndex: 0,
                buffer: 'A',
                sequencerState: 'IDLE',
                progress: 0,
                volume: 80
            });
            const [healthData, setHealthData] = useState({
                fps: Array(24).fill(60).map(() => 58 + Math.random() * 4),
                memory: Array(24).fill(45).map(() => 40 + Math.random() * 20),
                timestamps: Array.from({length: 24}, (_, i) => `${i}:00`)
            });
            const [syncGroups, setSyncGroups] = useState([
                { id: 'sg_1', name: 'Lobby Group', devices: ['dev_1'], drift: 0.0, model: 'Leader-Follower' },
                { id: 'sg_2', name: 'Retail Group', devices: ['dev_2'], drift: 0.0, model: 'Leader-Follower' }
            ]);
            const [settings, setSettings] = useState({
                mqtt: { broker: 'mqtt.edge-signage.local', port: 1883, clientId: 'edge-runtime-v3' },
                watchdog: { enabled: true, interval: 30, restartThreshold: 3 },
                engine: { hwAccel: true, preloadBuffers: 2, maxBitrate: 20000 },
                sync: { driftThreshold: 50, correctionInterval: 1000, ntpServer: 'pool.ntp.org' }
            });

            useEffect(() => {
                const interval = setInterval(() => {
                    setHealthData(prev => ({
                        fps: [...prev.fps.slice(1), 58 + Math.random() * 4],
                        memory: [...prev.memory.slice(1), 40 + Math.random() * 20],
                        timestamps: [...prev.timestamps.slice(1), new Date().toLocaleTimeString('en-US', {hour12: false, hour: '2-digit', minute:'2-digit'})]
                    }));
                }, 3000);
                return () => clearInterval(interval);
            }, []);

            return (
                <AppContext.Provider value={{
                    currentPage, setCurrentPage,
                    playlists, setPlaylists,
                    devices, setDevices,
                    assets, setAssets,
                    sidebarOpen, setSidebarOpen,
                    playerState, setPlayerState,
                    healthData,
                    syncGroups, setSyncGroups,
                    settings, setSettings
                }}>
                    {children}
                </AppContext.Provider>
            );
        };

        // --- Icons ---
        const Icon = ({ name, size = 20, className = '' }) => {
            const icons = {
                home: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m3 9 9-7 9 7v11a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2z"/><polyline points="9 22 9 12 15 12 15 22"/></svg>,
                list: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><line x1="8" y1="6" x2="21" y2="6"/><line x1="8" y1="12" x2="21" y2="12"/><line x1="8" y1="18" x2="21" y2="18"/><line x1="3" y1="6" x2="3.01" y2="6"/><line x1="3" y1="12" x2="3.01" y2="12"/><line x1="3" y1="18" x2="3.01" y2="18"/></svg>,
                monitor: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect width="20" height="14" x="2" y="3" rx="2"/><line x1="8" y1="21" x2="16" y2="21"/><line x1="12" y1="17" x2="12" y2="21"/></svg>,
                play: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polygon points="5 3 19 12 5 21 5 3"/></svg>,
                image: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect width="18" height="18" x="3" y="3" rx="2" ry="2"/><circle cx="9" cy="9" r="2"/><path d="m21 15-3.086-3.086a2 2 0 0 0-2.828 0L6 21"/></svg>,
                activity: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M22 12h-4l-3 9L9 3l-3 9H2"/></svg>,
                workflow: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect width="8" height="8" x="3" y="3" rx="2"/><path d="M7 11v4a2 2 0 0 0 2 2h4"/><rect width="8" height="8" x="13" y="13" rx="2"/></svg>,
                settings: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M12.22 2h-.44a2 2 0 0 0-2 2v.18a2 2 0 0 1-1 1.73l-.43.25a2 2 0 0 1-2 0l-.15-.08a2 2 0 0 0-2.73.73l-.22.38a2 2 0 0 0 .73 2.73l.15.1a2 2 0 0 1 1 1.72v.51a2 2 0 0 1-1 1.74l-.15.09a2 2 0 0 0-.73 2.73l.22.38a2 2 0 0 0 2.73.73l.15-.08a2 2 0 0 1 2 0l.43.25a2 2 0 0 1 1 1.73V20a2 2 0 0 0 2 2h.44a2 2 0 0 0 2-2v-.18a2 2 0 0 1 1-1.73l.43-.25a2 2 0 0 1 2 0l.15.08a2 2 0 0 0 2.73-.73l.22-.39a2 2 0 0 0-.73-2.73l-.15-.08a2 2 0 0 1-1-1.74v-.5a2 2 0 0 1 1-1.74l.15-.09a2 2 0 0 0 .73-2.73l-.22-.38a2 2 0 0 0-2.73-.73l-.15.08a2 2 0 0 1-2 0l-.43-.25a2 2 0 0 1-1-1.73V4a2 2 0 0 0-2-2z"/><circle cx="12" cy="12" r="3"/></svg>,
                menu: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><line x1="4" y1="12" x2="20" y2="12"/><line x1="4" y1="6" x2="20" y2="6"/><line x1="4" y1="18" x2="20" y2="18"/></svg>,
                x: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M18 6 6 18"/><path d="m6 6 12 12"/></svg>,
                plus: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M5 12h14"/><path d="M12 5v14"/></svg>,
                trash: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M3 6h18"/><path d="M19 6v14c0 1-1 2-2 2H7c-1 0-2-1-2-2V6"/><path d="M8 6V4c0-1 1-2 2-2h4c1 0 2 1 2 2v2"/></svg>,
                edit: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M17 3a2.85 2.83 0 1 1 4 4L7.5 20.5 2 22l1.5-5.5Z"/><path d="m15 5 4 4"/></svg>,
                check: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polyline points="20 6 9 17 4 12"/></svg>,
                chevronRight: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m9 18 6-6-6-6"/></svg>,
                pause: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect x="6" y="4" width="4" height="16"/><rect x="14" y="4" width="4" height="16"/></svg>,
                skipBack: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polygon points="19 20 9 12 19 4 19 20"/><line x1="5" y1="19" x2="5" y2="5"/></svg>,
                skipForward: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polygon points="5 4 15 12 5 20 5 4"/><line x1="19" y1="5" x2="19" y2="19"/></svg>,
                rotateCcw: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M3 12a9 9 0 1 0 9-9 9.75 9.75 0 0 0-6.74 2.74L3 12"/></svg>,
                volume: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polygon points="11 5 6 9 2 9 2 15 6 15 11 19 11 5"/><path d="M15.54 8.46a5 5 0 0 1 0 7.07"/></svg>,
                upload: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4"/><polyline points="17 8 12 3 7 8"/><line x1="12" y1="3" x2="12" y2="15"/></svg>,
                search: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><circle cx="11" cy="11" r="8"/><path d="m21 21-4.3-4.3"/></svg>,
                cpu: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><rect x="4" y="4" width="16" height="16" rx="2"/><rect x="9" y="9" width="6" height="6"/><path d="M15 2v2"/><path d="M15 20v2"/><path d="M2 15h2"/><path d="M2 9h2"/><path d="M20 15h2"/><path d="M20 9h2"/><path d="M9 2v2"/><path d="M9 20v2"/></svg>,
                wifi: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M5 12.55a11 11 0 0 1 14.08 0"/><path d="M1.42 9a16 16 0 0 1 21.16 0"/><path d="M8.53 16.11a6 6 0 0 1 6.95 0"/><line x1="12" y1="20" x2="12.01" y2="20"/></svg>,
                alert: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="m21.73 18-8-14a2 2 0 0 0-3.48 0l-8 14A2 2 0 0 0 4 21h16a2 2 0 0 0 1.73-3Z"/><line x1="12" y1="9" x2="12" y2="13"/><line x1="12" y1="17" x2="12.01" y2="17"/></svg>,
                clock: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><circle cx="12" cy="12" r="10"/><polyline points="12 6 12 12 16 14"/></svg>,
                zap: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><polygon points="13 2 3 14 12 14 11 22 21 10 12 10 13 2"/></svg>,
                save: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M19 21H5a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2h11l5 5v11a2 2 0 0 1-2 2z"/><polyline points="17 21 17 13 7 13 7 21"/><polyline points="7 3 7 8 15 8"/></svg>,
                refresh: <svg width={size} height={size} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" strokeLinejoin="round" className={className}><path d="M21 12a9 9 0 0 0-9-9 9.75 9.75 0 0 0-6.74 2.74L3 8"/><path d="M3 3v5h5"/><path d="M3 12a9 9 0 0 0 9 9 9.75 9.75 0 0 0 6.74-2.74L21 16"/><path d="M16 16h5v5"/></svg>
            };
            return icons[name] || null;
        };

        // --- Components ---

        const StatusBadge = ({ status }) => {
            const colors = {
                online: 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20',
                offline: 'text-slate-400 bg-slate-400/10 border-slate-400/20',
                degraded: 'text-amber-400 bg-amber-400/10 border-amber-400/20',
                critical: 'text-red-400 bg-red-400/10 border-red-400/20',
                active: 'text-primary bg-primary/10 border-primary/20',
                draft: 'text-slate-400 bg-slate-400/10 border-slate-400/20',
                archived: 'text-slate-500 bg-slate-500/10 border-slate-500/20',
                ready: 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20',
                cached: 'text-primary bg-primary/10 border-primary/20',
                error: 'text-red-400 bg-red-400/10 border-red-400/20',
                OK: 'text-emerald-400 bg-emerald-400/10 border-emerald-400/20',
                DEGRADED: 'text-amber-400 bg-amber-400/10 border-amber-400/20',
                CRITICAL: 'text-red-400 bg-red-400/10 border-red-400/20'
            };
            return (
                <span className={`inline-flex items-center gap-1.5 px-2.5 py-1 rounded-full text-xs font-medium border ${colors[status] || colors.offline}`}>
                    <span className={`w-1.5 h-1.5 rounded-full ${status === 'online' || status === 'active' || status === 'ready' || status === 'OK' ? 'bg-current status-dot' : 'bg-current'}`} />
                    {status}
                </span>
            );
        };

        const GlowCard = ({ children, className = '', glowColor = 'cyan' }) => (
            <div className={`glass-card rounded-xl p-4 glow-border-cyan shadow-glow-card ${className}`}>
                {children}
            </div>
        );

        const MetricCard = ({ title, value, subtitle, icon, color = 'primary', trend }) => (
            <GlowCard className="relative overflow-hidden">
                <div className="flex justify-between items-start mb-3">
                    <span className="text-xs font-mono text-slate-400 uppercase tracking-wider">{title}</span>
                    <span className={`text-${color}`}>{icon}</span>
                </div>
                <div className="text-3xl font-bold text-foreground mb-1">{value}</div>
                {subtitle && <div className="text-sm text-slate-400">{subtitle}</div>}
                {trend && (
                    <div className="mt-2 text-xs font-mono text-emerald-400 flex items-center gap-1">
                        <Icon name="check" size={12} /> {trend}
                    </div>
                )}
            </GlowCard>
        );

        // --- Pages ---

        const Dashboard = () => {
            const { devices, playlists, healthData } = useContext(AppContext);
            const onlineCount = devices.filter(d => d.status === 'online').length;
            const activePlaylists = playlists.filter(p => p.status === 'active').length;
            const chartRef = useRef(null);
            const chartInstance = useRef(null);

            useEffect(() => {
                if (chartRef.current) {
                    if (chartInstance.current) chartInstance.current.destroy();
                    const ctx = chartRef.current.getContext('2d');
                    chartInstance.current = new Chart(ctx, {
                        type: 'line',
                        data: {
                            labels: healthData.timestamps.slice(-12),
                            datasets: [{
                                label: 'FPS',
                                data: healthData.fps.slice(-12),
                                borderColor: 'hsl(187 100% 50%)',
                                backgroundColor: 'rgba(6, 182, 212, 0.1)',
                                borderWidth: 2,
                                tension: 0.4,
                                fill: true,
                                pointRadius: 0
                            }, {
                                label: 'Memory %',
                                data: healthData.memory.slice(-12),
                                borderColor: 'hsl(270 80% 65%)',
                                backgroundColor: 'rgba(168, 85, 247, 0.1)',
                                borderWidth: 2,
                                tension: 0.4,
                                fill: true,
                                pointRadius: 0
                            }]
                        },
                        options: {
                            responsive: true,
                            maintainAspectRatio: false,
                            plugins: { legend: { display: false } },
                            scales: {
                                x: { display: false },
                                y: { display: false, min: 0, max: 100 }
                            },
                            animation: { duration: 0 }
                        }
                    });
                }
                return () => { if (chartInstance.current) chartInstance.current.destroy(); };
            }, [healthData]);

            return (
                <div className="space-y-4 animate-slide-up pb-20">
                    <div className="px-4 pt-4">
                        <h1 className="text-2xl font-bold text-foreground mb-1">Runtime Dashboard</h1>
                        <p className="text-sm font-mono text-slate-400">Edge Signage Execution Platform — System Overview</p>
                    </div>

                    <div className="grid grid-cols-2 gap-3 px-4">
                        <MetricCard 
                            title="Devices Online" 
                            value={`${onlineCount} / ${devices.length}`} 
                            icon={<Icon name="monitor" size={18} />}
                            color="success"
                        />
                        <MetricCard 
                            title="Active Playlists" 
                            value={activePlaylists} 
                            icon={<Icon name="list" size={18} />}
                            color="primary"
                        />
                        <MetricCard 
                            title="Media Assets" 
                            value="6" 
                            icon={<Icon name="image" size={18} />}
                            color="accent"
                        />
                        <MetricCard 
                            title="System Health" 
                            value="80%" 
                            subtitle="Optimal" 
                            icon={<Icon name="activity" size={18} />}
                            color="success"
                            trend="+2.4%"
                        />
                    </div>

                    <div className="px-4">
                        <GlowCard>
                            <div className="flex justify-between items-center mb-4">
                                <h3 className="text-sm font-semibold text-foreground">Live Telemetry</h3>
                                <span className="text-xs font-mono text-primary flex items-center gap-1">
                                    <span className="w-2 h-2 rounded-full bg-primary status-dot animate-pulse" />
                                    LIVE
                                </span>
                            </div>
                            <div className="chart-container">
                                <canvas ref={chartRef} />
                            </div>
                            <div className="flex gap-4 mt-3 text-xs font-mono">
                                <div className="flex items-center gap-2">
                                    <span className="w-3 h-1 rounded-full bg-primary" />
                                    <span className="text-slate-400">FPS</span>
                                </div>
                                <div className="flex items-center gap-2">
                                    <span className="w-3 h-1 rounded-full bg-accent" />
                                    <span className="text-slate-400">Memory</span>
                                </div>
                            </div>
                        </GlowCard>
                    </div>

                    <div className="px-4">
                        <h3 className="text-sm font-semibold text-foreground mb-3">Device Status</h3>
                        <div className="space-y-2">
                            {devices.map(device => (
                                <div key={device.id} className="glass-card rounded-xl p-3 flex items-center justify-between">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-2 h-2 rounded-full ${device.status === 'online' ? 'bg-emerald-400 status-dot' : device.status === 'degraded' ? 'bg-amber-400' : 'bg-red-400'}`} />
                                        <div>
                                            <div className="text-sm font-medium text-foreground">{device.name}</div>
                                            <div className="text-xs font-mono text-slate-500">{device.device_id}</div>
                                        </div>
                                    </div>
                                    <StatusBadge status={device.status} />
                                </div>
                            ))}
                        </div>
                    </div>

                    <div className="px-4">
                        <h3 className="text-sm font-semibold text-foreground mb-3">System Events</h3>
                        <div className="space-y-2 font-mono text-xs">
                            {[
                                { time: '03:31:42', event: 'Device dev_4 heartbeat received', type: 'info' },
                                { time: '03:30:15', event: 'Playlist "Lobby Display" updated to v3', type: 'success' },
                                { time: '03:28:03', event: 'Device dev_3 memory threshold warning', type: 'warning' },
                                { time: '03:25:56', event: 'Sync group "Retail" drift corrected', type: 'info' },
                                { time: '03:22:11', event: 'Asset "Summer Vibes" cached locally', type: 'success' }
                            ].map((log, i) => (
                                <div key={i} className="glass-card rounded-lg p-3 flex gap-3 items-start">
                                    <span className="text-slate-500 whitespace-nowrap">{log.time}</span>
                                    <span className={log.type === 'warning' ? 'text-amber-400' : log.type === 'success' ? 'text-emerald-400' : 'text-slate-300'}>
                                        {log.event}
                                    </span>
                                </div>
                            ))}
                        </div>
                    </div>
                </div>
            );
        };

        const Playlists = () => {
            const { playlists, setPlaylists, setPlayerState } = useContext(AppContext);
            const [editing, setEditing] = useState(null);

            const deletePlaylist = (id) => {
                setPlaylists(prev => prev.filter(p => p.id !== id));
            };

            const loadPlaylist = (playlist) => {
                setPlayerState(prev => ({
                    ...prev,
                    currentPlaylist: playlist,
                    currentIndex: 0,
                    isPlaying: true,
                    sequencerState: 'PLAYING'
                }));
            };

            return (
                <div className="space-y-4 animate-slide-up pb-20">
                    <div className="px-4 pt-4 flex justify-between items-end">
                        <div>
                            <h1 className="text-2xl font-bold text-foreground mb-1">Playlists</h1>
                            <p className="text-sm font-mono text-slate-400">Declarative media sequences for deterministic execution</p>
                        </div>
                    </div>

                    <div className="px-4">
                        <button className="w-full bg-primary text-background font-semibold py-3 rounded-xl flex items-center justify-center gap-2 active:scale-95 transition-transform">
                            <Icon name="plus" size={20} />
                            New Playlist
                        </button>
                    </div>

                    <div className="px-4 space-y-3">
                        {playlists.map(playlist => (
                            <GlowCard key={playlist.id} className="group">
                                <div className="flex items-start justify-between mb-3">
                                    <div className="flex items-center gap-3">
                                        <div className="w-10 h-10 rounded-lg bg-primary/10 flex items-center justify-center text-primary">
                                            <Icon name="list" size={20} />
                                        </div>
                                        <div>
                                            <h3 className="font-semibold text-foreground text-sm">{playlist.name}</h3>
                                            <p className="text-xs font-mono text-slate-500">{playlist.items.length} items · v{playlist.version}</p>
                                        </div>
                                    </div>
                                    <div className="flex gap-2">
                                        <button onClick={() => loadPlaylist(playlist)} className="p-2 rounded-lg bg-primary/10 text-primary active:scale-90 transition-transform">
                                            <Icon name="play" size={16} />
                                        </button>
                                        <button onClick={() => deletePlaylist(playlist.id)} className="p-2 rounded-lg bg-destructive/10 text-destructive active:scale-90 transition-transform">
                                            <Icon name="trash" size={16} />
                                        </button>
                                    </div>
                                </div>
                                <div className="flex items-center justify-between">
                                    <StatusBadge status={playlist.status} />
                                    <span className="text-xs font-mono text-slate-500">{playlist.loop ? 'Loop' : 'Once'}</span>
                                </div>
                                {editing === playlist.id && (
                                    <div className="mt-3 pt-3 border-t border-white/5 space-y-2">
                                        {playlist.items.map((item, idx) => (
                                            <div key={item.id} className="flex items-center gap-2 text-xs font-mono text-slate-400">
                                                <span className="w-5 h-5 rounded bg-muted flex items-center justify-center text-foreground">{idx + 1}</span>
                                                <span className="truncate flex-1">{item.name}</span>
                                                <span className="text-primary">{item.type}</span>
                                                <span>{item.duration}ms</span>
                                            </div>
                                        ))}
                                    </div>
                                )}
                            </GlowCard>
                        ))}
                    </div>
                </div>
            );
        };

        const Devices = () => {
            const { devices, setDevices, playlists } = useContext(AppContext);
            const [selectedDevice, setSelectedDevice] = useState(null);

            const updateShadow = (deviceId, key, value) => {
                setDevices(prev => prev.map(d => {
                    if (d.id !== deviceId) return d;
                    return {
                        ...d,
                        shadow_state: {
                            ...d.shadow_state,
                            desired: { ...d.shadow_state.desired, [key]: value },
                            version: d.shadow_state.version + 1
                        }
                    };
                }));
            };

            return (
                <div className="space-y-4 animate-slide-up pb-20">
                    <div className="px-4 pt-4">
                        <h1 className="text-2xl font-bold text-foreground mb-1">Devices</h1>
                        <p className="text-sm font-mono text-slate-400">Fleet management with MQTT Device Shadow</p>
                    </div>

                    <div className="px-4 space-y-3">
                        {devices.map(device => (
                            <GlowCard key={device.id} className="cursor-pointer active:scale-[0.98] transition-transform" onClick={() => setSelectedDevice(selectedDevice === device.id ? null : device.id)}>
                                <div className="flex items-center justify-between mb-2">
                                    <div className="flex items-center gap-3">
                                        <div className={`w-2 h-2 rounded-full ${device.status === 'online' ? 'bg-emerald-400 status-dot' : device.status === 'degraded' ? 'bg-amber-400' : 'bg-red-400'}`} />
                                        <div>
                                            <h3 className="font-semibold text-foreground text-sm">{device.name}</h3>
                                            <p className="text-xs font-mono text-slate-500">{device.platform} · {device.resolution}</p>
                                        </div>
                                    </div>
                                    <StatusBadge status={device.status} />
                                </div>

                                {selectedDevice === device.id && (
                                    <div className="mt-3 pt-3 border-t border-white/5 space-y-3 animate-slide-up">
                                        <div className="grid grid-cols-2 gap-2 text-xs font-mono">
                                            <div className="bg-muted rounded-lg p-2">
                                                <div className="text-slate-500 mb-1">Location</div>
                                                <div className="text-foreground">{device.location}</div>
                                            </div>
                                            <div className="bg-muted rounded-lg p-2">
                                                <div className="text-slate-500 mb-1">Uptime</div>
                                                <div className="text-foreground">{device.health.uptime_hours}h</div>
                                            </div>
                                        </div>

                                        <div className="bg-muted rounded-lg p-3 space-y-2">
                                            <div className="flex justify-between items-center mb-2">
                                                <span className="text-xs font-semibold text-primary">Device Shadow</span>
                                                <span className="text-xs font-mono text-slate-500">v{device.shadow_state.version}</span>
                                            </div>

                                            <div className="space-y-2">
                                                <div>
                                                    <label className="text-xs text-slate-400 block mb-1">Playlist</label>
                                                    <select 
                                                        value={device.shadow_state.desired.playlist || ''}
                                                        onChange={(e) => updateShadow(device.id, 'playlist', e.target.value || null)}
                                                        className="w-full rounded-lg px-3 py-2 text-xs font-mono"
                                                        onClick={e => e.stopPropagation()}
                                                    >
                                                        <option value="">None</option>
                                                        {playlists.map(p => (
                                                            <option key={p.id} value={p.id}>{p.name}</option>
                                                        ))}
                                                    </select>
                                                </div>
                                                <div className="grid grid-cols-2 gap-2">
                                                    <div>
                                                        <label className="text-xs text-slate-400 block mb-1">Volume</label>
                                                        <input 
                                                            type="range" min="0" max="100" 
                                                            value={device.shadow_state.desired.volume}
                                                            onChange={(e) => updateShadow(device.id, 'volume', parseInt(e.target.value))}
                                                            className="w-full accent-primary"
                                                            onClick={e => e.stopPropagation()}
                                                        />
                                                    </div>
                                                    <div>
                                                        <label className="text-xs text-slate-400 block mb-1">Brightness</label>
                                                        <input 
                                                            type="range" min="0" max="100" 
                                                            value={device.shadow_state.desired.brightness}
                                                            onChange={(e) => updateShadow(device.id, 'brightness', parseInt(e.target.value))}
                                                            className="w-full accent-primary"
                                                            onClick={e => e.stopPropagation()}
                                                        />
                                                    </div>
                                                </div>
                                            </div>

                                            <div className="pt-2 border-t border-white/5">
                                                <div className="text-xs text-slate-500 mb-1">Reported State</div>
                                                <div className="text-xs font-mono text-emerald-400">
                                                    {JSON.stringify(device.shadow_state.reported)}
                                                </div>
                                            </div>
                                        </div>

                                        <div className="grid grid-cols-3 gap-2 text-center">
                                            <div className="bg-muted rounded-lg p-2">
                                                <div className="text-lg font-bold text-foreground">{device.health.memory_usage}%</div>
                                                <div className="text-[10px] text-slate-500 uppercase">Memory</div>
                                            </div>
                                            <div className="bg-muted rounded-lg p-2">
                                                <div className="text-lg font-bold text-foreground">{device.health.frame_drops}</div>
                                                <div className="text-[10px] text-slate-500 uppercase">Drops</div>
                                            </div>
                                            <div className="bg-muted rounded-lg p-2">
                                                <div className="text-lg font-bold text-foreground">{device.health.decode_errors}</div>
                                                <div className="text-[10px] text-slate-500 uppercase">Errors</div>
                                            </div>
                                        </div>
                                    </div>
                                )}
                            </GlowCard>
                        ))}
                    </div>
                </div>
            );
        };

        const PlayerEngine = () => {
            const { playerState, setPlayerState, playlists } = useContext(AppContext);
            const [selectedPlaylist, setSelectedPlaylist] = useState('');
            const videoRefA = useRef(null);
            const videoRefB = useRef(null);
            const [currentItem, setCurrentItem] = useState(null);

            useEffect(() => {
                if (playerState.currentPlaylist && playerState.currentPlaylist.items.length > 0) {
                    setCurrentItem(playerState.currentPlaylist.items[playerState.currentIndex]);
                }
            }, [playerState.currentPlaylist, playerState.currentIndex]);

            const loadPlaylist = () => {
                const pl = playlists.find(p => p.id === selectedPlaylist);
                if (pl) {
                    setPlayerState(prev => ({
                        ...prev,
                        currentPlaylist: pl,
                        currentIndex: 0,
                        sequencerState: 'READY',
                        isPlaying: false
                    }));
                }
            };

            const togglePlay = () => {
                setPlayerState(prev => ({
                    ...prev,
                    isPlaying: !prev.isPlaying,
                    sequencerState: !prev.isPlaying ? 'PLAYING' : 'PAUSED'
                }));
            };

            const nextItem = () => {
                if (!playerState.currentPlaylist) return;
                const next = (playerState.currentIndex + 1) % playerState.currentPlaylist.items.length;
                setPlayerState(prev => ({
                    ...prev,
                    currentIndex: next,
                    buffer: prev.buffer === 'A' ? 'B' : 'A',
                    sequencerState: 'TRANSITION'
                }));
                setTimeout(() => {
                    setPlayerState(prev => ({ ...prev, sequencerState: 'PLAYING' }));
                }, 300);
            };

            return (
                <div className="space-y-4 animate-slide-up pb-20">
                    <div className="px-4 pt-4">
                        <h1 className="text-2xl font-bold text-foreground mb-1">Player Engine</h1>
                        <p className="text-sm font-mono text-slate-400">Dual-buffer A/B playback with zero-gap transitions</p>
                    </div>

                    <div className="px-4">
                        <div className="glass-card rounded-xl overflow-hidden bg-black aspect-video relative">
                            {currentItem ? (
                                <>
                                    {currentItem.type === 'video' ? (
                                        <video 
                                            ref={playerState.buffer === 'A' ? videoRefA : videoRefB}
                                            src={currentItem.url}
                                            className="w-full h-full object-cover"
                                            autoPlay={playerState.isPlaying}
                                            muted
                                            loop={false}
                                        />
                                    ) : currentItem.type === 'image' ? (
                                        <img src={currentItem.url} className="w-full h-full object-cover" alt={currentItem.name} />
                                    ) : (
                                        <iframe src={currentItem.url} className="w-full h-full border-0" title={currentItem.name} />
                                    )}
                                    <div className="absolute bottom-0 left-0 right-0 bg-gradient-to-t from-black/80 to-transparent p-4">
                                        <div className="text-sm font-medium text-foreground">{currentItem.name}</div>
                                        <div className="text-xs font-mono text-slate-400">{currentItem.type.toUpperCase()} · {currentItem.duration}ms</div>
                                    </div>
                                </>
                            ) : (
                                <div className="w-full h-full flex items-center justify-center text-slate-500 font-mono text-sm">
                                    <div className="text-center">
                                        <div className="mb-2 opacity-50">
                                            <Icon name="play" size={48} className="mx-auto" />
                                        </div>
                                        AWAITING PLAYBACK
                                    </div>
                                </div>
                            )}

                            {playerState.sequencerState === 'TRANSITION' && (
                                <div className="absolute inset-0 bg-primary/20 flex items-center justify-center">
                                    <div className="text-primary font-mono font-bold animate-pulse">TRANSITIONING</div>
                                </div>
                            )}
                        </div>
                    </div>

                    <div className="px-4">
                        <div className="flex items-center gap-2 mb-4">
                            <select 
                                value={selectedPlaylist}
                                onChange={(e) => setSelectedPlaylist(e.target.value)}
                                className="flex-1 rounded-lg px-3 py-2 text-sm"
                            >
                                <option value="">Select Playlist...</option>
                                {playlists.map(p => (
                                    <option key={p.id} value={p.id}>{p.name}</option>
                                ))}
                            </select>
                            <button onClick={loadPlaylist} className="bg-primary text-background px-4 py-2 rounded-lg text-sm font-semibold active:scale-95 transition-transform">
                                Load
                            </button>
                        </div>

                        <div className="glass-card rounded-xl p-4">
                            <div className="flex items-center justify-center gap-4 mb-4">
                                <button onClick={() => setPlayerState(p => ({...p, currentIndex: 0}))} className="p-2 text-slate-400 active:text-primary transition-colors">
                                    <Icon name="rotateCcw" size={20} />
                                </button>
                                <button className="p-2 text-slate-400 active:text-primary transition-colors">
                                    <Icon name="skipBack" size={20} />
                                </button>
                                <button 
                                    onClick={togglePlay}
                                    className={`w-14 h-14 rounded-full flex items-center justify-center active:scale-90 transition-all ${playerState.isPlaying ? 'bg-foreground text-background' : 'bg-primary text-background shadow-glow-cyan'}`}
                                >
                                    <Icon name={playerState.isPlaying ? "pause" : "play"} size={24} />
                                </button>
