                        </button>
                    </div>
                </div>
            );
        };

        // --- Layout ---

        const Sidebar = () => {
            const { currentPage, setCurrentPage, sidebarOpen, setSidebarOpen } = useContext(AppContext);

            const navItems = [
                { id: 'dashboard', label: 'Dashboard', icon: 'home' },
                { id: 'playlists', label: 'Playlists', icon: 'list' },
                { id: 'devices', label: 'Devices', icon: 'monitor' },
                { id: 'player', label: 'Player Engine', icon: 'play' },
                { id: 'assets', label: 'Media Assets', icon: 'image' },
                { id: 'health', label: 'Health Monitor', icon: 'activity' },
                { id: 'sync', label: 'Multi-Sync', icon: 'workflow' },
                { id: 'settings', label: 'Settings', icon: 'settings' },
            ];

            return (
                <>
                    {/* Overlay */}
                    {sidebarOpen && (
                        <div 
                            className="fixed inset-0 bg-black/60 backdrop-blur-sm z-40"
                            onClick={() => setSidebarOpen(false)}
                        />
                    )}

                    {/* Sidebar */}
                    <div className={`fixed top-0 left-0 h-full w-72 bg-card border-r border-white/5 z-50 transform transition-transform duration-300 ${sidebarOpen ? 'translate-x-0' : '-translate-x-full'}`}>
                        <div className="p-6 border-b border-white/5">
                            <div className="flex items-center gap-3">
                                <div className="w-10 h-10 rounded-xl bg-primary/10 flex items-center justify-center">
                                    <Icon name="zap" size={24} className="text-primary" />
                                </div>
                                <div>
                                    <h1 className="font-bold text-foreground tracking-tight">EDGE SIGNAGE</h1>
                                    <p className="text-[10px] font-mono text-slate-500 tracking-widest">RUNTIME v3.0</p>
                                </div>
                            </div>
                        </div>

                        <nav className="p-4 space-y-1">
                            {navItems.map(item => (
                                <button
                                    key={item.id}
                                    onClick={() => {
                                        setCurrentPage(item.id);
                                        setSidebarOpen(false);
                                    }}
                                    className={`w-full flex items-center gap-3 px-4 py-3 rounded-lg text-sm font-medium transition-all ${
                                        currentPage === item.id 
                                            ? 'nav-item-active text-primary' 
                                            : 'text-slate-400 hover:text-foreground hover:bg-white/5'
                                    }`}
                                >
                                    <Icon name={item.icon} size={18} />
                                    {item.label}
                                    {currentPage === item.id && (
                                        <span className="ml-auto w-1.5 h-1.5 rounded-full bg-primary status-dot" />
                                    )}
                                </button>
                            ))}
                        </nav>

                        <div className="absolute bottom-0 left-0 right-0 p-4 border-t border-white/5">
                            <div className="flex items-center gap-2 text-xs font-mono text-slate-500">
                                <span className="w-2 h-2 rounded-full bg-emerald-400 status-dot" />
                                Runtime Active
                            </div>
                        </div>
                    </div>
                </>
            );
        };

        const Header = () => {
            const { setSidebarOpen, currentPage } = useContext(AppContext);
            const titles = {
                dashboard: 'Dashboard',
                playlists: 'Playlists',
                devices: 'Devices',
                player: 'Player Engine',
                assets: 'Media Assets',
                health: 'Health Monitor',
                sync: 'Multi-Sync',
                settings: 'Settings'
            };

            return (
                <header className="sticky top-0 z-30 bg-background/80 backdrop-blur-xl border-b border-white/5">
                    <div className="flex items-center justify-between px-4 h-14">
                        <button 
                            onClick={() => setSidebarOpen(true)}
                            className="p-2 -ml-2 text-slate-400 active:text-primary transition-colors"
                        >
                            <Icon name="menu" size={24} />
                        </button>
                        <span className="text-sm font-semibold text-foreground">{titles[currentPage]}</span>
                        <div className="w-8" />
                    </div>
                </header>
            );
        };

        const App = () => {
            const { currentPage } = useContext(AppContext);

            const pages = {
                dashboard: <Dashboard />,
                playlists: <Playlists />,
                devices: <Devices />,
                player: <PlayerEngine />,
                assets: <MediaAssets />,
                health: <HealthMonitor />,
                sync: <MultiSync />,
                settings: <RuntimeSettings />
            };

            return (
                <div className="min-h-screen bg-background text-foreground">
                    <Sidebar />
                    <Header />
                    <main className="pt-2">
                        {pages[currentPage]}
                    </main>
                </div>
            );
        };

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(
            <AppProvider>
                <App />
            </AppProvider>
        );
    </script>
</body>
</html>
